const fieldsByCategory = {
  invoice: ['invoiceNumber', 'amount', 'currency'],
  customer_request: ['orderNumber', 'requestedChange'],
  other: ['summary'],
};
const dataFields = Object.values(fieldsByCategory).flat();
const requiredFields = ['category', ...dataFields];

function validate(response) {
  const content = response.message?.content;
  if (typeof content !== 'string' || content.trim() === '') {
    return { valid: false, error: 'Ollama response has no message.content text.' };
  }

  let result;
  try {
    result = JSON.parse(content);
  } catch {
    return { valid: false, error: 'Ollama message.content is not valid JSON.' };
  }

  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    return { valid: false, error: 'Expected a JSON object.' };
  }
  if (Object.keys(result).length !== requiredFields.length ||
      !requiredFields.every(field => Object.hasOwn(result, field))) {
    return { valid: false, error: 'Expected exactly the classifier fields.' };
  }
  if (typeof result.category !== 'string' || !Object.hasOwn(fieldsByCategory, result.category)) {
    return { valid: false, error: 'Unknown document category.' };
  }

  const applicableFields = fieldsByCategory[result.category];
  for (const field of dataFields) {
    const value = result[field];
    if (value === null) continue;
    if (!applicableFields.includes(field)) {
      return { valid: false, error: field + ' must be null for this category.' };
    }
    const validValue = field === 'amount'
      ? Number.isFinite(value)
      : typeof value === 'string' && value.trim() !== '';
    if (!validValue) {
      return { valid: false, error: 'Invalid value for ' + field + '.' };
    }
  }
  if (result.currency !== null && !/^[A-Z]{3}$/.test(result.currency)) {
    return { valid: false, error: 'Currency must be a three-letter uppercase code.' };
  }

  return { valid: true, result };
}

return $input.all().map((item, index) => ({
  json: validate(item.json),
  pairedItem: { item: index },
}));
